const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const seattle = ee.Geometry.Point([-122.3321, 47.6062]); // Approximate center of Seattle
  const startDate = '2021-09-01';
  const endDate = '2021-11-30';
  const rainfallThresholdCm = 40; // The threshold in centimeters

  // 2. Data Acquisition & Check
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(seattle);

  const collectionSize = await chirps.size().getInfo();
  console.log(`CHIRPS images for Seattle (${startDate} to ${endDate}): ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("No CHIRPS images found for the specified date range and location.");
    console.log("C1"); // Empty Collection
    return;
  }

  // 3. Processing & Calculation
  // CHIRPS 'precipitation' band is in millimeters.
  // Sum all daily precipitation images over the period.
  const totalPrecipitationImage = chirps.sum();

  // Reduce the summed image to get the total precipitation at the Seattle point.
  // Using a scale of 5000m, which is close to CHIRPS's native resolution (~5.5km),
  // and appropriate for regional averages to avoid excessive computation.
  const precipitationStats = await totalPrecipitationImage.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: seattle,
    scale: 5000, // CHIRPS resolution is ~5.5km
    maxPixels: 1e9,
    crs: 'EPSG:4326' // Explicitly set CRS
  }).getInfo();

  const totalPrecipitationMm = precipitationStats ? precipitationStats['precipitation'] : null;

  // 4. Validation & Final Answer
  if (totalPrecipitationMm === null || isNaN(totalPrecipitationMm)) {
    console.log("Calculation of total precipitation failed or resulted in an invalid value.");
    console.log("C3"); // Calculation Failure
    return;
  }

  const totalPrecipitationCm = totalPrecipitationMm / 10.0; // Convert mm to cm

  console.log(`Total precipitation in Seattle from ${startDate} to ${endDate}: ${totalPrecipitationCm.toFixed(2)} cm`);

  // To check for valid pixels, we can also count them, though for a sum reduction over a point,
  // if precipitation value is returned, it means pixels were there.
  const pixelCount = await totalPrecipitationImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: seattle,
    scale: 5000,
    maxPixels: 1e9,
    crs: 'EPSG:4326'
  }).getInfo();

  const validPixels = pixelCount ? pixelCount['precipitation'] : 0;
  console.log(`Valid pixels counted for reduction: ${validPixels}`);

  if (validPixels === 0) {
    console.log("No valid pixels found after processing for the region.");
    console.log("C2"); // No Valid Pixels
    return;
  }

  if (totalPrecipitationCm >= rainfallThresholdCm) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
